"""R63 S3 batch B07-B09 blind predictions generator. Asserts id set == batches B07+B08+B09 (60)."""
import json, pathlib
BASE = pathlib.Path("/home/hatch/workspace/divination/benchmark/phase3/runs/round63")
batches = json.loads((BASE/"batches.json").read_text())
IDS = batches["B07"]+batches["B08"]+batches["B09"]
assert len(IDS)==60 and len(set(IDS))==60

def T(cm,ru,di,reason): return {"changed_main":cm,"reserve_used":ru,"disputed":di,"reason":reason}
F = lambda r: T(False,False,False,r)
