# ---- write out ----
assert set(P.keys())==set(IDS), (set(IDS)-set(P.keys()), set(P.keys())-set(IDS))
outdir = BASE/"predictions"; outdir.mkdir(exist_ok=True)
sizes={}
for cid in IDS:
    text, basis, conf, trig = P[cid]
    assert 0.0 <= conf <= 1.0
    assert set(trig.keys())=={"changed_main","reserve_used","disputed","reason"}
    obj = {"case_id":cid, "prediction_text":text, "basis":basis, "confidence":conf, "trigger":trig}
    p = outdir/f"{cid}.json"
    p.write_text(json.dumps(obj, ensure_ascii=False, indent=1), encoding="utf-8")
    sizes[cid]=p.stat().st_size
cm=sum(1 for c in IDS if P[c][3]["changed_main"]); ru=sum(1 for c in IDS if P[c][3]["reserve_used"]); di=sum(1 for c in IDS if P[c][3]["disputed"])
print("count", len(IDS), "written", len(sizes))
print("trigger true counts: changed_main", cm, "reserve_used", ru, "disputed", di)
for cid in IDS: print(cid, sizes[cid])
